<dialog id="template-asset-dialog" class="studio-dialog asset-dialog"><div class="dialog-shell"><header><div><p class="eyebrow">Template asset manager</p><h2>Choose an image</h2></div><button type="button" class="icon-button" data-template-close-dialog="template-asset-dialog" aria-label="Close">×</button></header><div class="asset-library-tools"><label class="button button-secondary" for="template-asset-file">Upload image<input type="file" id="template-asset-file" accept="image/jpeg,image/png,image/webp"></label><input type="search" id="template-asset-search" placeholder="Search by file name or alt text" aria-label="Search template images"><span id="template-asset-requirement" class="field-hint"></span></div><div class="asset-library" id="template-asset-library"></div><footer><button type="button" class="button button-ghost" data-template-close-dialog="template-asset-dialog">Cancel</button></footer></div></dialog>

<dialog id="template-asset-details-dialog" class="studio-dialog asset-details-dialog"><form class="dialog-shell" id="template-asset-details-form"><header><div><p class="eyebrow">Template asset manager</p><h2>Image details</h2></div><button type="button" class="icon-button" data-template-close-dialog="template-asset-details-dialog" aria-label="Close">×</button></header><div class="asset-details-body"><div class="asset-detail-preview" id="template-asset-detail-preview"></div><div class="asset-detail-fields"><strong id="template-asset-detail-name"></strong><span id="template-asset-detail-dimensions" class="field-hint"></span><label>Alt text<input id="template-asset-alt" required maxlength="250" placeholder="Describe the image for readers who cannot see it"></label><p class="field-hint">Alt text follows the image when this template is cloned.</p></div></div><footer><button type="button" class="button button-ghost" id="template-asset-details-back">Back</button><button type="submit" class="button button-secondary" id="template-asset-details-save">Save details</button><button type="button" class="button button-primary" id="template-asset-details-use">Use image</button></footer></form></dialog>

<dialog id="template-crop-dialog" class="studio-dialog crop-dialog"><div class="dialog-shell"><header><div><p class="eyebrow">Fit template image</p><h2>Crop to <span id="template-crop-target-label"></span></h2></div><button type="button" class="icon-button" data-template-close-dialog="template-crop-dialog" aria-label="Close">×</button></header><div class="crop-body"><div class="crop-stage"><canvas id="template-crop-canvas"></canvas><span>Drag to reposition</span></div><div class="crop-controls"><label>Zoom<input type="range" id="template-crop-zoom" min="1" max="4" step="0.01" value="1"></label><div><button type="button" class="button button-secondary" id="template-crop-rotate-left">↶ Rotate left</button><button type="button" class="button button-secondary" id="template-crop-rotate-right">↷ Rotate right</button></div><p class="field-hint">The crop completely fills the module’s required image area.</p></div></div><footer><button type="button" class="button button-ghost" id="template-crop-back">Back</button><button type="button" class="button button-primary" id="template-crop-apply">Crop and use</button></footer></div></dialog>
